import { ARMOR_PIECES, shapeBlocks, type BlockSpec, type EffectSpec, type ElementSpec, type ItemSpec, type MobSpec, type OreSpec, type Project, type ToolSpec, type TreeSpec } from "../../schema.js";
import { resolveRef } from "./refs.js";
import { TWO_BY_TWO_SHAPES } from "../../trees.js";
import { allParts, pickAnimations, type EntityModelDef, type ModelAnimation, type ModelPartDef } from "../../blockbench.js";

export const GENERATED_HEADER =
  "// Generated by Mod Creator from spec/. Do not edit: this file is rewritten on every generate.\n" +
  "// Put hand-written code in src/main/java instead.";

/** `ruby_ore` -> `RUBY_ORE` */
export const constName = (id: string) => id.toUpperCase();

/** `ruby_ore` -> `RubyOre` */
export const pascal = (id: string) =>
  id.split(/[_-]/).filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");

const float = (n: number) => (Number.isInteger(n) ? `${n}.0f` : `${n}f`);
const double = (n: number) => (Number.isInteger(n) ? `${n}.0` : `${n}`);

/** Java expression for an item: a ModContent field for our own ids, a registry lookup for anything else. */
function itemExpr(modId: string, ref: string): string {
  const full = resolveRef(modId, ref);
  if (full.startsWith(`${modId}:`)) return `ModContent.${constName(full.slice(modId.length + 1))}`;
  return `BuiltInRegistries.ITEM.getValue(Identifier.parse("${full}"))`;
}

/** Java expression for `stack` matching an item id or `#tag`. */
function stackTest(modId: string, ref: string): string {
  if (ref.startsWith("#")) return `stack.is(TagKey.create(Registries.ITEM, Identifier.parse("${resolveRef(modId, ref).slice(1)}")))`;
  return `stack.is(${itemExpr(modId, ref)})`;
}

function blockProperties(spec: BlockSpec): string {
  const b = spec.block;
  let props = "BlockBehaviour.Properties.of()";
  props += `\n\t\t\t.strength(${float(b.hardness)}, ${float(b.resistance)})`;
  props += `\n\t\t\t.sound(SoundType.${b.sound.toUpperCase()})`;
  if (b.requiresTool) props += "\n\t\t\t.requiresCorrectToolForDrops()";
  if (b.lightLevel > 0) props += `\n\t\t\t.lightLevel(state -> ${b.lightLevel})`;
  return props;
}

/**
 * Fields for a block's or tree's shape blocks, which copy the base block's properties. Wooden ones use oak's
 * sounds and timings (doors open by hand, buttons stay pressed longer); the rest use stone's.
 */
function shapeFields(spec: BlockSpec | TreeSpec, base: string, wood: boolean, use: (...names: string[]) => void): { fields: string[]; tabItems: string[] } {
  const set = wood ? "BlockSetType.OAK" : "BlockSetType.STONE";
  const copy = `BlockBehaviour.Properties.ofFullCopy(${base})`;
  const fields: string[] = [];
  const tabItems: string[] = [];
  for (const b of shapeBlocks(spec)) {
    let factory: string;
    let props = copy;
    switch (b.shape) {
      case "stairs":
        use("net.minecraft.world.level.block.StairBlock");
        // StairBlock's constructor is protected, hence the empty subclass.
        factory = `properties -> new StairBlock(${base}.defaultBlockState(), properties) {}`;
        break;
      case "slab":
        use("net.minecraft.world.level.block.SlabBlock");
        factory = "SlabBlock::new";
        break;
      case "wall":
        use("net.minecraft.world.level.block.WallBlock");
        factory = "WallBlock::new";
        props += ".forceSolidOn()";
        break;
      case "fence":
        use("net.minecraft.world.level.block.FenceBlock");
        factory = "FenceBlock::new";
        props += ".forceSolidOn()";
        break;
      case "fenceGate":
        use("net.minecraft.world.level.block.FenceGateBlock", "net.minecraft.world.level.block.state.properties.WoodType");
        factory = "properties -> new FenceGateBlock(WoodType.OAK, properties)";
        props += ".forceSolidOn()";
        break;
      case "door":
        use("net.minecraft.world.level.block.DoorBlock", "net.minecraft.world.level.block.state.properties.BlockSetType", "net.minecraft.world.level.material.PushReaction");
        factory = `properties -> new DoorBlock(${set}, properties) {}`;
        props += ".noOcclusion().pushReaction(PushReaction.POPPED)";
        break;
      case "trapdoor":
        use("net.minecraft.world.level.block.TrapDoorBlock", "net.minecraft.world.level.block.state.properties.BlockSetType");
        factory = `properties -> new TrapDoorBlock(${set}, properties) {}`;
        props += ".noOcclusion()";
        break;
      case "button":
        use("net.minecraft.world.level.block.ButtonBlock", "net.minecraft.world.level.block.state.properties.BlockSetType", "net.minecraft.world.level.material.PushReaction");
        factory = `properties -> new ButtonBlock(${set}, ${wood ? 30 : 20}, properties) {}`;
        props += ".noCollision().strength(0.5f).pushReaction(PushReaction.POPPED)";
        break;
      case "pressurePlate":
        use("net.minecraft.world.level.block.PressurePlateBlock", "net.minecraft.world.level.block.state.properties.BlockSetType", "net.minecraft.world.level.material.PushReaction");
        factory = `properties -> new PressurePlateBlock(${set}, properties) {}`;
        props += ".forceSolidOn().noCollision().strength(0.5f).pushReaction(PushReaction.POPPED)";
        break;
    }
    fields.push(`	public static final Block ${constName(b.id)} = registerBlock("${b.id}", ${factory},
			${props}, true);`);
    tabItems.push(`${constName(b.id)}.asItem()`);
  }
  return { fields, tabItems };
}

function rarity(r: string): string {
  return r !== "common" ? `.rarity(Rarity.${r.toUpperCase()})` : "";
}

/** Java for the `Holder<MobEffect>` of an effect ref: this mod's field, or a vanilla effect looked up by id. */
function effectHolder(modId: string, ref: string): string {
  const full = resolveRef(modId, ref);
  return full.startsWith(`${modId}:`) ? `${constName(full.slice(modId.length + 1))}_EFFECT` : `BuiltInRegistries.MOB_EFFECT.get(Identifier.parse("${full}")).orElseThrow()`;
}

const ticks = (seconds: number) => Math.max(1, Math.round(seconds * 20));

function itemProperties(modId: string, spec: ItemSpec, use: (...names: string[]) => void): string {
  let props = "new Item.Properties()";
  if (spec.item.maxStackSize !== 64) props += `.stacksTo(${spec.item.maxStackSize})`;
  props += rarity(spec.item.rarity);
  const food = spec.item.food;
  if (food) {
    use("net.minecraft.world.food.FoodProperties");
    props += `\n\t\t\t.food(new FoodProperties.Builder().nutrition(${food.nutrition}).saturationModifier(${float(food.saturation)})`;
    props += food.alwaysEdible ? ".alwaysEdible().build()" : ".build()";
    if (food.effects.length) {
      use(
        "net.minecraft.world.effect.MobEffectInstance",
        "net.minecraft.world.item.component.Consumables",
        "net.minecraft.world.item.consume_effects.ApplyStatusEffectsConsumeEffect",
      );
      props += ",\n\t\t\t\tConsumables.defaultFood()";
      for (const e of food.effects) {
        props += `\n\t\t\t\t\t.onConsume(new ApplyStatusEffectsConsumeEffect(new MobEffectInstance(${effectHolder(modId, e.effect)}, ${ticks(e.seconds)}, ${e.amplifier}), ${float(e.chance)}))`;
      }
      props += ".build()";
    }
    props += ")";
  }
  return props;
}

const OPERATIONS: Record<EffectSpec["effect"]["modifiers"][number]["operation"], string> = {
  add: "ADD_VALUE",
  multiply_base: "ADD_MULTIPLIED_BASE",
  multiply_total: "ADD_MULTIPLIED_TOTAL",
};

/** Vanilla potion timings: long lasts 8/3 as long, strong is level II for half the time. */
export function potionVariants(e: EffectSpec): { id: string; ticks: number; amplifier: number }[] {
  const p = e.effect.potion;
  if (!p) return [];
  const base = p.seconds * 20;
  return [
    { id: e.id, ticks: base, amplifier: 0 },
    ...(p.longer ? [{ id: `long_${e.id}`, ticks: Math.round((base * 8) / 3), amplifier: 0 }] : []),
    ...(p.stronger ? [{ id: `strong_${e.id}`, ticks: Math.round(base / 2), amplifier: 1 }] : []),
  ];
}

/** Effect and potion fields. Effects come first so the foods and potions below can use them. */
function effectFields(modId: string, effects: EffectSpec[], use: (...names: string[]) => void): string[] {
  if (!effects.length) return [];
  use("net.minecraft.core.Holder", "net.minecraft.world.effect.MobEffect", "net.minecraft.world.effect.MobEffectCategory");
  const out: string[] = [];
  for (const e of effects) {
    const C = constName(e.id);
    const color = `0x${e.effect.color.slice(1).toLowerCase()}`;
    let value = `new MobEffect(MobEffectCategory.${e.effect.category.toUpperCase()}, ${color}) {}`;
    for (const m of e.effect.modifiers) {
      use("net.minecraft.world.entity.ai.attributes.AttributeModifier", "net.minecraft.world.entity.ai.attributes.Attributes");
      value += `\n\t\t\t.addAttributeModifier(Attributes.${m.attribute.toUpperCase()}, id("effect.${e.id}.${m.attribute}"), ${m.amount}, AttributeModifier.Operation.${OPERATIONS[m.operation]})`;
    }
    let field = `\t/** ${e.name} (spec/effects/${e.id}.json) */\n\tpublic static final Holder<MobEffect> ${C}_EFFECT = registerEffect("${e.id}", ${value});`;
    const variants = potionVariants(e);
    if (variants.length) {
      use("net.minecraft.world.effect.MobEffectInstance", "net.minecraft.world.item.alchemy.Potion");
      for (const v of variants) {
        const amp = v.amplifier ? `, ${v.amplifier}` : "";
        field += `\n\tpublic static final Holder<Potion> ${constName(v.id)}_POTION = registerPotion("${v.id}",\n\t\t\tnew Potion("${modId}.${e.id}", new MobEffectInstance(${C}_EFFECT, ${v.ticks}${amp})));`;
      }
    }
    out.push(field);
  }
  return out;
}

const TIER_TAGS: Record<ToolSpec["tool"]["tier"], string> = {
  wood: "INCORRECT_FOR_WOODEN_TOOL",
  stone: "INCORRECT_FOR_STONE_TOOL",
  copper: "INCORRECT_FOR_COPPER_TOOL",
  iron: "INCORRECT_FOR_IRON_TOOL",
  gold: "INCORRECT_FOR_GOLD_TOOL",
  diamond: "INCORRECT_FOR_DIAMOND_TOOL",
  netherite: "INCORRECT_FOR_NETHERITE_TOOL",
};

/** Item tag holding a tool's or armor set's repair item; written by the resource generator. */
export const repairTag = (id: string) => `${id}_repair_items`;

/** Default sounds for mobs that borrow a vanilla body. */
const MOB_SOUNDS: Partial<Record<MobSpec["mob"]["model"], { ambient: string; hurt: string; death: string }>> = {
  pig: { ambient: "minecraft:entity.pig.ambient", hurt: "minecraft:entity.pig.hurt", death: "minecraft:entity.pig.death" },
  cow: { ambient: "minecraft:entity.cow.ambient", hurt: "minecraft:entity.cow.hurt", death: "minecraft:entity.cow.death" },
};

const MOB_MODELS: Record<"pig" | "cow", { model: string; baby: string; layer: string; shadow: number; pkg: string }> = {
  pig: { model: "PigModel", baby: "BabyPigModel", layer: "PIG", shadow: 0.7, pkg: "net.minecraft.client.model.animal.pig" },
  cow: { model: "CowModel", baby: "BabyCowModel", layer: "COW", shadow: 0.7, pkg: "net.minecraft.client.model.animal.cow" },
};

const tab = (t: string) => `CreativeModeTabs.${t.toUpperCase()}`;

/** The generated `ModContent` class: registers every element, fills creative tabs and hooks into worldgen. */
export function modContentJava(project: Project, elements: ElementSpec[]): string {
  const modId = project.modId;
  const pkg = `${project.package}.generated`;
  const of = <K extends ElementSpec["kind"]>(kind: K) => elements.filter((e): e is Extract<ElementSpec, { kind: K }> => e.kind === kind);
  const blocks = of("block");
  const items = of("item");
  const tools = of("tool");
  const armors = of("armor");
  const trees = of("tree");
  const plants = of("plant");
  const mobs = of("mob");
  const ores = of("ore");
  const sounds = of("sound");
  const effects = of("effect");

  const imports = new Set<string>([
    "java.util.function.Function",
    "net.fabricmc.fabric.api.creativetab.v1.CreativeModeTabEvents",
    "net.minecraft.core.Registry",
    "net.minecraft.core.registries.BuiltInRegistries",
    "net.minecraft.core.registries.Registries",
    "net.minecraft.resources.Identifier",
    "net.minecraft.resources.ResourceKey",
    "net.minecraft.world.item.BlockItem",
    "net.minecraft.world.item.CreativeModeTabs",
    "net.minecraft.world.item.Item",
    "net.minecraft.world.item.Rarity",
    "net.minecraft.world.level.block.Block",
    "net.minecraft.world.level.block.SoundType",
    "net.minecraft.world.level.block.state.BlockBehaviour",
  ]);
  const use = (...names: string[]) => names.forEach((n) => imports.add(n));

  const materials: string[] = [];
  const fields: string[] = [];
  const body: string[] = [];
  /** Creative tab entries grouped by tab, in spec order. */
  const tabs = new Map<string, string[]>();
  const addToTab = (t: string | undefined, ref: string) => t && tabs.set(t, [...(tabs.get(t) ?? []), ref]);

  if (sounds.length) {
    use("net.minecraft.sounds.SoundEvent");
    fields.push(
      sounds.map((s) => `\t/** ${s.name} (spec/sounds/${s.id}.json) */\n\tpublic static final SoundEvent ${constName(s.id)}_SOUND = registerSound("${s.id}");`).join("\n"),
    );
  }

  fields.push(...effectFields(modId, effects, use));

  for (const b of blocks) {
    const factory = b.customClass ? `${b.customClass}::new` : "Block::new";
    fields.push(
      `\t/** ${b.name} (spec/blocks/${b.id}.json) */\n` +
        `\tpublic static final Block ${constName(b.id)} = registerBlock("${b.id}", ${factory},\n\t\t\t${blockProperties(b)}, ${b.hasItem});`,
    );
    if (b.hasItem) addToTab(b.creativeTab, `${constName(b.id)}.asItem()`);
    const shapes = shapeFields(b, constName(b.id), b.block.sound === "wood", use);
    if (shapes.fields.length) fields.push(`\t// ${b.name} shapes\n${shapes.fields.join("\n")}`);
    for (const ref of shapes.tabItems) addToTab(b.creativeTab ?? "building_blocks", ref);
  }

  for (const t of trees) {
    use(
      "net.minecraft.world.level.block.Blocks",
      "net.minecraft.world.level.block.RotatedPillarBlock",
      "net.minecraft.world.level.block.SaplingBlock",
      "net.minecraft.world.level.block.TintedParticleLeavesBlock",
      "net.minecraft.world.level.block.grower.TreeGrower",
      "net.minecraft.util.random.WeightedList",
      "net.fabricmc.fabric.api.registry.FlammableBlockRegistry",
    );
    const C = constName(t.id);
    const feature = `ResourceKey.create(Registries.FEATURE, id("${t.id}"))`;
    fields.push(
      `\t// ${t.name} wood (spec/trees/${t.id}.json)\n` +
        // Dark oak and the giant shapes only grow from four saplings in a square, like vanilla dark oak.
        (TWO_BY_TWO_SHAPES.includes(t.tree.shape)
          ? `\tprivate static final TreeGrower ${C}_GROWER = new TreeGrower("${modId}:${t.id}",\n` +
            `\t\t\tWeightedList.of(), WeightedList.of(${feature}), WeightedList.of(), null);\n`
          : `\tprivate static final TreeGrower ${C}_GROWER = new TreeGrower("${modId}:${t.id}",\n` +
            `\t\t\tWeightedList.of(${feature}), WeightedList.of(), WeightedList.of(), ${feature});\n`) +
        `\tpublic static final Block ${C}_LOG = registerBlock("${t.id}_log", RotatedPillarBlock::new,\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_LOG), true);\n` +
        `\tpublic static final Block ${C}_PLANKS = registerBlock("${t.id}_planks", Block::new,\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_PLANKS), true);\n` +
        `\tpublic static final Block ${C}_LEAVES = registerBlock("${t.id}_leaves", properties -> new TintedParticleLeavesBlock(0.01f, properties),\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_LEAVES), true);\n` +
        `\tpublic static final Block ${C}_SAPLING = registerBlock("${t.id}_sapling", properties -> new SaplingBlock(${C}_GROWER, properties),\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_SAPLING), true);`,
    );
    for (const part of ["LOG", "PLANKS", "LEAVES", "SAPLING"]) addToTab(t.creativeTab, `${C}_${part}.asItem()`);
    const shapes = shapeFields(t, `${C}_PLANKS`, true, use);
    if (shapes.fields.length) fields.push(`\t// ${t.name} wood set\n${shapes.fields.join("\n")}`);
    for (const ref of shapes.tabItems) addToTab("building_blocks", ref);
    body.push(
      `\t\t// ${t.name} wood burns like oak.\n` +
        `\t\tFlammableBlockRegistry.getDefaultInstance().add(${C}_LOG, 5, 5);\n` +
        `\t\tFlammableBlockRegistry.getDefaultInstance().add(${C}_PLANKS, 5, 20);\n` +
        `\t\tFlammableBlockRegistry.getDefaultInstance().add(${C}_LEAVES, 30, 60);` +
        shapeBlocks(t)
          .filter((s) => ["stairs", "slab", "fence", "fenceGate"].includes(s.shape))
          .map((s) => `\n\t\tFlammableBlockRegistry.getDefaultInstance().add(${constName(s.id)}, 5, 20);`)
          .join(""),
    );
  }

  if (trees.some((t) => t.tree.shape === "custom")) {
    use(`${pkg}.world.CustomTreeFeature`);
    body.push(
      `\t\t// Grows hand-built trees (spec/trees with "shape": "custom").\n` +
        `\t\tRegistry.register(BuiltInRegistries.FEATURE_TYPE, id("custom_tree"), CustomTreeFeature.CODEC);`,
    );
  }

  for (const p of plants) {
    use("net.minecraft.world.level.block.Blocks", "net.minecraft.world.level.block.BushBlock");
    const factory = p.customClass ? `${p.customClass}::new` : "BushBlock::new";
    let props = "BlockBehaviour.Properties.ofFullCopy(Blocks.SHORT_GRASS)";
    if (!p.plant.offset) props += ".offsetType(BlockBehaviour.OffsetType.NONE)";
    fields.push(
      `\t/** ${p.name} (spec/plants/${p.id}.json) */\n` +
        `\tpublic static final Block ${constName(p.id)} = registerBlock("${p.id}", ${factory},\n\t\t\t${props}, true);`,
    );
    addToTab(p.creativeTab, `${constName(p.id)}.asItem()`);
  }

  for (const i of items) {
    const factory = i.customClass ? `${i.customClass}::new` : "Item::new";
    fields.push(
      `\t/** ${i.name} (spec/items/${i.id}.json) */\n` +
        `\tpublic static final Item ${constName(i.id)} = registerItem("${i.id}", ${factory}, ${itemProperties(modId, i, use)});`,
    );
    addToTab(i.creativeTab, constName(i.id));
  }

  for (const t of tools) {
    use("net.minecraft.world.item.ToolMaterial", "net.minecraft.tags.BlockTags", "net.minecraft.tags.TagKey");
    const C = constName(t.id);
    const x = t.tool;
    materials.push(
      `\tprivate static final ToolMaterial ${C}_MATERIAL = new ToolMaterial(BlockTags.${TIER_TAGS[x.tier]},\n` +
        `\t\t\t${x.durability}, ${float(x.miningSpeed)}, 0.0f, ${x.enchantability}, TagKey.create(Registries.ITEM, id("${repairTag(t.id)}")));`,
    );
    const factory = t.customClass ? `${t.customClass}::new` : "Item::new";
    fields.push(
      `\t/** ${t.name} (spec/tools/${t.id}.json) */\n` +
        `\tpublic static final Item ${C} = registerItem("${t.id}", ${factory},\n` +
        `\t\t\tnew Item.Properties().${x.type}(${C}_MATERIAL, ${float(x.attackDamage)}, ${float(x.attackSpeed)})${rarity(x.rarity)});`,
    );
    addToTab(t.creativeTab, C);
  }

  for (const a of armors) {
    use(
      "java.util.Map",
      "net.minecraft.sounds.SoundEvents",
      "net.minecraft.tags.TagKey",
      "net.minecraft.world.item.equipment.ArmorMaterial",
      "net.minecraft.world.item.equipment.ArmorType",
      "net.minecraft.world.item.equipment.EquipmentAssets",
    );
    const C = constName(a.id);
    const x = a.armor;
    const d = x.defense;
    materials.push(
      `\tprivate static final ArmorMaterial ${C}_MATERIAL = new ArmorMaterial(${x.durability},\n` +
        `\t\t\tMap.of(ArmorType.HELMET, ${d.helmet}, ArmorType.CHESTPLATE, ${d.chestplate}, ArmorType.LEGGINGS, ${d.leggings}, ArmorType.BOOTS, ${d.boots}, ArmorType.BODY, ${d.chestplate}),\n` +
        `\t\t\t${x.enchantability}, SoundEvents.ARMOR_EQUIP_${x.equipSound.toUpperCase()}, ${float(x.toughness)}, ${float(x.knockbackResistance)},\n` +
        `\t\t\tTagKey.create(Registries.ITEM, id("${repairTag(a.id)}")),\n` +
        `\t\t\tResourceKey.create(EquipmentAssets.ROOT_ID, id("${a.id}")));`,
    );
    for (const piece of ARMOR_PIECES) {
      if (!x.pieces[piece]) continue;
      const pid = `${a.id}_${piece}`;
      fields.push(
        `\t/** ${a.name} ${piece} (spec/armor/${a.id}.json) */\n` +
          `\tpublic static final Item ${constName(pid)} = registerItem("${pid}", Item::new,\n` +
          `\t\t\tnew Item.Properties().humanoidArmor(${C}_MATERIAL, ArmorType.${piece.toUpperCase()})${rarity(x.rarity)});`,
      );
      addToTab(a.creativeTab, constName(pid));
    }
  }

  for (const m of mobs) {
    use(
      "net.minecraft.world.entity.EntityType",
      "net.minecraft.world.entity.Entity",
      "net.minecraft.world.entity.MobCategory",
      "net.minecraft.world.entity.SpawnPlacements",
      "net.minecraft.world.entity.SpawnPlacementTypes",
      "net.minecraft.world.entity.ai.attributes.Attributes",
      "net.minecraft.world.item.SpawnEggItem",
      "net.minecraft.world.level.levelgen.Heightmap",
      "net.fabricmc.fabric.api.object.builder.v1.entity.FabricDefaultAttributeRegistry",
      `${pkg}.entity.${pascal(m.id)}`,
    );
    const C = constName(m.id);
    const P = pascal(m.id);
    fields.push(
      `\t/** ${m.name} (spec/mobs/${m.id}.json) */\n` +
        `\tpublic static final EntityType<${P}> ${C} = registerEntity("${m.id}",\n` +
        `\t\t\tEntityType.Builder.of(${P}::new, MobCategory.${m.mob.behavior === "hostile" ? "MONSTER" : "CREATURE"}).sized(${float(m.mob.width)}, ${float(m.mob.height)}));\n` +
        `\tpublic static final Item ${C}_SPAWN_EGG = registerItem("${m.id}_spawn_egg", SpawnEggItem::new, new Item.Properties().spawnEgg(${C}));`,
    );
    addToTab("spawn_eggs", `${C}_SPAWN_EGG`);
    const hostile = m.mob.behavior === "hostile";
    const attributes = [
      `.add(Attributes.MAX_HEALTH, ${double(m.mob.health)})`,
      `.add(Attributes.MOVEMENT_SPEED, ${double(m.mob.speed)})`,
      ...(m.mob.behavior !== "animal" ? [`.add(Attributes.ATTACK_DAMAGE, ${double(m.mob.attackDamage)})`] : []),
      ...(m.mob.flies ? [`.add(Attributes.FLYING_SPEED, ${double(Math.round(m.mob.speed * 2 * 1000) / 1000)})`] : []),
    ];
    body.push(
      `\t\t// ${m.name} (spec/mobs/${m.id}.json)\n` +
        `\t\tFabricDefaultAttributeRegistry.register(${C}, ${hostile ? "Monster.createMonsterAttributes()" : "Animal.createAnimalAttributes()"}\n` +
        attributes.map((a) => `\t\t\t\t${a}`).join("\n") +
        ");\n" +
        `\t\tSpawnPlacements.register(${C}, SpawnPlacementTypes.ON_GROUND, Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, ${hostile ? "Monster::checkMonsterSpawnRules" : "Animal::checkAnimalSpawnRules"});`,
    );
    use(hostile ? MOB_BASE.hostile.imp : MOB_BASE.animal.imp);
  }

  const tabCode = [...tabs].map(
    ([t, refs]) =>
      `\t\tCreativeModeTabEvents.modifyOutputEvent(${tab(t)}).register(output -> {\n` +
      refs.map((r) => `\t\t\toutput.accept(${r});`).join("\n") +
      "\n\t\t});",
  );

  const SELECTORS: Record<OreSpec["ore"]["replaces"], string> = {
    stone: "foundInOverworld",
    deepslate: "foundInOverworld",
    stone_and_deepslate: "foundInOverworld",
    netherrack: "foundInTheNether",
    end_stone: "foundInTheEnd",
  };
  if (ores.length) {
    use(
      "net.fabricmc.fabric.api.biome.v1.BiomeModifications",
      "net.fabricmc.fabric.api.biome.v1.BiomeSelectors",
      "net.minecraft.world.level.levelgen.GenerationStep",
    );
  }
  const oreCode = ores.map(
    (o) =>
      `\t\t// ${o.name} (spec/worldgen/${o.id}.json)\n` +
      `\t\tBiomeModifications.addFeature(BiomeSelectors.${SELECTORS[o.ore.replaces]}(), GenerationStep.Decoration.UNDERGROUND_ORES,\n` +
      `\t\t\t\tResourceKey.create(Registries.PLACED_FEATURE, id("${o.id}")));`,
  );
  const registerBody = [...tabCode, ...body, ...oreCode];

  const entityHelper = mobs.length
    ? `

\tprivate static <T extends Entity> EntityType<T> registerEntity(String name, EntityType.Builder<T> builder) {
\t\tResourceKey<EntityType<?>> key = ResourceKey.create(Registries.ENTITY_TYPE, id(name));
\t\treturn Registry.register(BuiltInRegistries.ENTITY_TYPE, key, builder.build(key));
\t}`
    : "";

  return `${GENERATED_HEADER}
package ${pkg};

${sortImports(imports)}

public final class ModContent {
\tpublic static final String MOD_ID = "${modId}";
${materials.length ? `\n${materials.join("\n")}\n` : ""}
${fields.join("\n\n")}

\tprivate ModContent() {
\t}

\t/** Call once from your mod initializer. Loading this class registers everything above. */
\tpublic static void register() {
${registerBody.join("\n") || "\t\t// Nothing else to register."}
\t}

\tprivate static Block registerBlock(String name, Function<BlockBehaviour.Properties, Block> factory,
\t\t\tBlockBehaviour.Properties properties, boolean withItem) {
\t\tResourceKey<Block> blockKey = ResourceKey.create(Registries.BLOCK, id(name));
\t\tBlock block = factory.apply(properties.setId(blockKey));
\t\tif (withItem) {
\t\t\tResourceKey<Item> itemKey = ResourceKey.create(Registries.ITEM, id(name));
\t\t\tRegistry.register(BuiltInRegistries.ITEM, itemKey,
\t\t\t\t\tnew BlockItem(block, new Item.Properties().setId(itemKey).useBlockDescriptionPrefix()));
\t\t}
\t\treturn Registry.register(BuiltInRegistries.BLOCK, blockKey, block);
\t}

${sounds.length ? `\tprivate static SoundEvent registerSound(String name) {
\t\treturn Registry.register(BuiltInRegistries.SOUND_EVENT, id(name), SoundEvent.createVariableRangeEvent(id(name)));
\t}

` : ""}${effects.length ? `\tprivate static Holder<MobEffect> registerEffect(String name, MobEffect effect) {
\t\treturn Registry.registerForHolder(BuiltInRegistries.MOB_EFFECT, id(name), effect);
\t}

` : ""}${effects.some((e) => e.effect.potion) ? `\tprivate static Holder<Potion> registerPotion(String name, Potion potion) {
\t\treturn Registry.registerForHolder(BuiltInRegistries.POTION, id(name), potion);
\t}

` : ""}\tprivate static Item registerItem(String name, Function<Item.Properties, Item> factory, Item.Properties properties) {
\t\tResourceKey<Item> key = ResourceKey.create(Registries.ITEM, id(name));
\t\treturn Registry.register(BuiltInRegistries.ITEM, key, factory.apply(properties.setId(key)));
\t}${entityHelper}

\tstatic Identifier id(String path) {
\t\treturn Identifier.fromNamespaceAndPath(MOD_ID, path);
\t}
}
`;
}

/** `java.*` first, then the rest, each group sorted, like IntelliJ's default. */
function sortImports(imports: Set<string>): string {
  const all = [...imports].sort();
  const java = all.filter((i) => i.startsWith("java."));
  const rest = all.filter((i) => !i.startsWith("java."));
  return [java, rest]
    .filter((g) => g.length)
    .map((g) => g.map((i) => `import ${i};`).join("\n"))
    .join("\n\n");
}

/** Java class each behavior extends. */
const MOB_BASE: Record<MobSpec["mob"]["behavior"], { cls: string; imp: string }> = {
  animal: { cls: "Animal", imp: "net.minecraft.world.entity.animal.Animal" },
  neutral: { cls: "Animal", imp: "net.minecraft.world.entity.animal.Animal" },
  tameable: { cls: "TamableAnimal", imp: "net.minecraft.world.entity.TamableAnimal" },
  hostile: { cls: "Monster", imp: "net.minecraft.world.entity.monster.Monster" },
};

/**
 * One class per mob. Its behavior picks the base class and AI goals: an animal wanders, panics, follows its food
 * and breeds; a neutral one fights back; a tameable one is tamed with its food, sits and follows its owner; a hostile
 * one hunts players. Flying mobs swap walking for flying, like parrots.
 */
export function mobEntityJava(project: Project, m: MobSpec): string {
  const modId = project.modId;
  const P = pascal(m.id);
  const { behavior, flies } = m.mob;
  const base = MOB_BASE[behavior];
  const breeds = behavior !== "hostile";
  const sounds = { ...MOB_SOUNDS[m.mob.model], ...m.mob.sounds };
  // A Blockbench mob has no vanilla animal to take sounds from, so it is silent unless the spec names some.
  const sound = (ref: string | undefined) => (ref ? `BuiltInRegistries.SOUND_EVENT.getValue(Identifier.parse("${resolveRef(modId, ref)}"))` : "null");
  const test = breeds && m.mob.food ? stackTest(modId, m.mob.food) : "false";

  const imports = new Set<string>([
    "net.minecraft.core.registries.BuiltInRegistries",
    "net.minecraft.resources.Identifier",
    "net.minecraft.sounds.SoundEvent",
    "net.minecraft.world.damagesource.DamageSource",
    "net.minecraft.world.entity.EntityType",
    "net.minecraft.world.entity.ai.goal.FloatGoal",
    "net.minecraft.world.entity.ai.goal.LookAtPlayerGoal",
    "net.minecraft.world.entity.ai.goal.RandomLookAroundGoal",
    "net.minecraft.world.entity.player.Player",
    "net.minecraft.world.level.Level",
    base.imp,
  ]);
  const use = (...names: string[]) => names.forEach((n) => imports.add(n));
  if (test.includes("TagKey")) use("net.minecraft.core.registries.Registries", "net.minecraft.tags.TagKey");
  if (breeds) {
    use(
      "net.minecraft.server.level.ServerLevel",
      "net.minecraft.world.entity.AgeableMob",
      "net.minecraft.world.entity.EntitySpawnReason",
      "net.minecraft.world.entity.ai.goal.BreedGoal",
      "net.minecraft.world.entity.ai.goal.FollowParentGoal",
      "net.minecraft.world.entity.ai.goal.TemptGoal",
      "net.minecraft.world.item.ItemStack",
    );
  }
  const stroll = flies ? "WaterAvoidingRandomFlyingGoal" : "WaterAvoidingRandomStrollGoal";
  use(`net.minecraft.world.entity.ai.goal.${stroll}`);

  // [priority, goal] for goalSelector and targetSelector.
  const goals: [number, string][] = [[0, "new FloatGoal(this)"]];
  const targets: [number, string][] = [];
  const fights = behavior !== "animal";
  if (fights) use("net.minecraft.world.entity.ai.goal.MeleeAttackGoal", "net.minecraft.world.entity.ai.goal.target.HurtByTargetGoal");
  switch (behavior) {
    case "animal":
      use("net.minecraft.world.entity.ai.goal.PanicGoal");
      goals.push([1, "new PanicGoal(this, 1.25)"]);
      break;
    case "neutral":
      goals.push([1, "new MeleeAttackGoal(this, 1.2, true)"]);
      targets.push([1, "new HurtByTargetGoal(this).setAlertOthers()"]);
      break;
    case "tameable":
      use(
        "net.minecraft.world.entity.ai.goal.SitWhenOrderedToGoal",
        "net.minecraft.world.entity.ai.goal.FollowOwnerGoal",
        "net.minecraft.world.entity.ai.goal.target.OwnerHurtByTargetGoal",
        "net.minecraft.world.entity.ai.goal.target.OwnerHurtTargetGoal",
      );
      goals.push([2, "new SitWhenOrderedToGoal(this)"], [3, "new MeleeAttackGoal(this, 1.0, true)"], [4, "new FollowOwnerGoal(this, 1.0, 10.0f, 2.0f)"]);
      targets.push([1, "new OwnerHurtByTargetGoal(this)"], [2, "new OwnerHurtTargetGoal(this)"], [3, "new HurtByTargetGoal(this)"]);
      break;
    case "hostile":
      use("net.minecraft.world.entity.ai.goal.target.NearestAttackableTargetGoal");
      goals.push([2, "new MeleeAttackGoal(this, 1.0, false)"]);
      targets.push([1, "new HurtByTargetGoal(this)"], [2, "new NearestAttackableTargetGoal<>(this, Player.class, true)"]);
      break;
  }
  if (breeds) {
    goals.push([5, "new BreedGoal(this, 1.0)"], [6, "new TemptGoal(this, 1.2, this::isFood, false)"], [6, "new FollowParentGoal(this, 1.1)"]);
  }
  goals.push([7, `new ${stroll}(this, 1.0)`], [8, "new LookAtPlayerGoal(this, Player.class, 6.0f)"], [8, "new RandomLookAroundGoal(this)"]);

  const methods: string[] = [];
  if (breeds) {
    methods.push(`\t@Override
\tpublic boolean isFood(ItemStack stack) {
\t\treturn ${test};
\t}

\t@Override
\tpublic AgeableMob getBreedOffspring(ServerLevel level, AgeableMob partner) {
\t\treturn ModContent.${constName(m.id)}.create(level, EntitySpawnReason.BREEDING);
\t}`);
  }
  if (behavior === "tameable") {
    use("net.minecraft.world.InteractionHand", "net.minecraft.world.InteractionResult");
    methods.push(`\t/** Feeding it while wild tames it one time in three; its owner's empty hand makes it sit or stand. */
\t@Override
\tpublic InteractionResult mobInteract(Player player, InteractionHand hand) {
\t\tItemStack stack = player.getItemInHand(hand);
\t\tif (!this.isTame() && this.isFood(stack)) {
\t\t\tthis.usePlayerItem(player, hand, stack);
\t\t\tif (!this.level().isClientSide()) {
\t\t\t\tif (this.getRandom().nextInt(3) == 0) {
\t\t\t\t\tthis.tame(player);
\t\t\t\t\tthis.navigation.stop();
\t\t\t\t\tthis.setOrderedToSit(true);
\t\t\t\t\tthis.level().broadcastEntityEvent(this, (byte) 7);
\t\t\t\t} else {
\t\t\t\t\tthis.level().broadcastEntityEvent(this, (byte) 6);
\t\t\t\t}
\t\t\t}
\t\t\treturn InteractionResult.SUCCESS;
\t\t}
\t\tif (this.isTame() && this.isOwnedBy(player) && stack.isEmpty()) {
\t\t\tif (!this.level().isClientSide()) {
\t\t\t\tthis.setOrderedToSit(!this.isOrderedToSit());
\t\t\t\tthis.navigation.stop();
\t\t\t}
\t\t\treturn InteractionResult.SUCCESS;
\t\t}
\t\treturn super.mobInteract(player, hand);
\t}`);
  }
  let constructorExtra = "";
  if (flies) {
    use(
      "net.minecraft.core.BlockPos",
      "net.minecraft.world.entity.ai.control.FlyingMoveControl",
      "net.minecraft.world.entity.ai.navigation.FlyingPathNavigation",
      "net.minecraft.world.entity.ai.navigation.PathNavigation",
      "net.minecraft.world.level.block.state.BlockState",
    );
    constructorExtra = "\n\t\tthis.moveControl = new FlyingMoveControl<>(this, 10, false);";
    methods.push(`\t@Override
\tprotected PathNavigation createNavigation(Level level) {
\t\tFlyingPathNavigation navigation = new FlyingPathNavigation(this, level);
\t\tnavigation.setCanOpenDoors(false);
\t\tnavigation.setCanFloat(true);
\t\treturn navigation;
\t}

\t/** Flyers don't take fall damage. */
\t@Override
\tpublic boolean causeFallDamage(double distance, float multiplier, DamageSource source) {
\t\treturn false;
\t}

\t@Override
\tprotected void checkFallDamage(double y, boolean onGround, BlockState state, BlockPos pos) {
\t}`);
  }
  methods.push(`\t@Override
\tprotected SoundEvent getAmbientSound() {
\t\treturn ${sound(sounds.ambient)};
\t}

\t@Override
\tprotected SoundEvent getHurtSound(DamageSource source) {
\t\treturn ${sound(sounds.hurt)};
\t}

\t@Override
\tprotected SoundEvent getDeathSound() {
\t\treturn ${sound(sounds.death)};
\t}`);

  const addGoals = (selector: string, list: [number, string][]) => list.map(([n, g]) => `\t\tthis.${selector}.addGoal(${n}, ${g});`);
  const what = { animal: "An animal", neutral: "A neutral animal that fights back", tameable: "A tameable animal", hostile: "A hostile mob" }[behavior];
  return `${GENERATED_HEADER}
package ${project.package}.generated.entity;

${[...imports].sort().map((i) => `import ${i};`).join("\n")}

import ${project.package}.generated.ModContent;

/** ${m.name} (spec/mobs/${m.id}.json): ${what.toLowerCase()}${flies ? " that flies" : ""}. For custom behavior, subclass it in src/main/java. */
public class ${P} extends ${base.cls} {
\tpublic ${P}(EntityType<? extends ${P}> type, Level level) {
\t\tsuper(type, level);${constructorExtra}
\t}

\t@Override
\tprotected void registerGoals() {
${[...addGoals("goalSelector", goals), ...addGoals("targetSelector", targets)].join("\n")}
\t}

${methods.join("\n\n")}
}
`;
}

/** A renderer that draws the mob with a vanilla body and its own textures, switching to the baby body for babies. */
export function mobRendererJava(project: Project, m: MobSpec): string {
  if (m.mob.model === "blockbench") return blockbenchRendererJava(project, m);
  const P = pascal(m.id);
  const model = MOB_MODELS[m.mob.model];
  const M = model.model;
  return `${GENERATED_HEADER}
package ${project.package}.generated.client;

import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.model.AdultAndBabyModelPair;
import net.minecraft.client.model.geom.ModelLayers;
import net.minecraft.client.renderer.SubmitNodeCollector;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.client.renderer.state.level.CameraRenderState;
import net.minecraft.resources.Identifier;
import ${model.pkg}.${model.baby};
import ${model.pkg}.${M};

import ${project.package}.generated.ModContent;
import ${project.package}.generated.entity.${P};

/** Draws ${m.name} with the vanilla ${m.mob.model} body (spec/mobs/${m.id}.json). */
public class ${P}Renderer extends MobRenderer<${P}, LivingEntityRenderState, ${M}> {
\tprivate static final Identifier TEXTURE = Identifier.fromNamespaceAndPath(ModContent.MOD_ID, "textures/entity/${m.id}.png");
\tprivate static final Identifier BABY_TEXTURE = Identifier.fromNamespaceAndPath(ModContent.MOD_ID, "textures/entity/${m.id}_baby.png");

\tprivate final AdultAndBabyModelPair<${M}> models;

\tpublic ${P}Renderer(EntityRendererProvider.Context context) {
\t\tthis(context, new AdultAndBabyModelPair<>(new ${M}(context.bakeLayer(ModelLayers.${model.layer})),
\t\t\t\tnew ${model.baby}(context.bakeLayer(ModelLayers.${model.layer}_BABY))));
\t}

\tprivate ${P}Renderer(EntityRendererProvider.Context context, AdultAndBabyModelPair<${M}> models) {
\t\tsuper(context, models.adultModel(), ${float(model.shadow)});
\t\tthis.models = models;
\t}

\t@Override
\tpublic LivingEntityRenderState createRenderState() {
\t\treturn new LivingEntityRenderState();
\t}

\t@Override
\tpublic Identifier getTextureLocation(LivingEntityRenderState state) {
\t\treturn state.isBaby ? BABY_TEXTURE : TEXTURE;
\t}

\t@Override
\tpublic void submit(LivingEntityRenderState state, PoseStack poseStack, SubmitNodeCollector collector, CameraRenderState camera) {
\t\tthis.model = this.models.getModel(state.isBaby);
\t\tsuper.submit(state, poseStack, collector, camera);
\t}
}
`;
}

/** Client entrypoint: registers renderers. Listed in fabric.mod.json under "client". */
export function modContentClientJava(project: Project, elements: ElementSpec[]): string {
  const mobs = elements.filter((e): e is MobSpec => e.kind === "mob");
  const custom = mobs.filter((m) => m.mob.model === "blockbench");
  const pkg = `${project.package}.generated`;
  const imports = mobs.length
    ? [
        ...(custom.length ? ["import net.fabricmc.fabric.api.client.rendering.v1.ModelLayerRegistry;"] : []),
        "import net.minecraft.client.renderer.entity.EntityRenderers;",
        ...mobs.map((m) => `import ${pkg}.client.${pascal(m.id)}Renderer;`),
        ...custom.map((m) => `import ${pkg}.client.${pascal(m.id)}Model;`),
      ]
    : [];
  const layers = custom.map((m) => `		ModelLayerRegistry.registerModelLayer(${pascal(m.id)}Model.LAYER, ${pascal(m.id)}Model::createBodyLayer);`);
  return `${GENERATED_HEADER}
package ${pkg};

import net.fabricmc.api.ClientModInitializer;
${imports.length ? "\n" + imports.join("\n") + "\n" : ""}
/** Client-side setup for generated content. fabric.mod.json lists this class as the "client" entrypoint. */
public final class ModContentClient implements ClientModInitializer {
\t@Override
\tpublic void onInitializeClient() {
${[...layers, ...mobs.map((m) => `\t\tEntityRenderers.register(ModContent.${constName(m.id)}, ${pascal(m.id)}Renderer::new);`)].join("\n") || "\t\t// Nothing to set up yet."}
\t}
}
`;
}

/** Java files besides ModContent, keyed by path relative to the generated package folder. */
export function extraJavaFiles(project: Project, elements: ElementSpec[], models: Record<string, EntityModelDef> = {}): Map<string, string> {
  const out = new Map<string, string>();
  out.set("ModContentClient.java", modContentClientJava(project, elements));
  if (elements.some((e) => e.kind === "tree" && e.tree.shape === "custom")) out.set("world/CustomTreeFeature.java", customTreeFeatureJava(project));
  for (const e of elements) {
    if (e.kind !== "mob") continue;
    out.set(`entity/${pascal(e.id)}.java`, mobEntityJava(project, e));
    out.set(`client/${pascal(e.id)}Renderer.java`, mobRendererJava(project, e));
    const model = e.mob.model === "blockbench" && e.mob.blockbench ? models[e.mob.blockbench] : undefined;
    if (model) out.set(`client/${pascal(e.id)}Model.java`, blockbenchModelJava(project, e, model));
  }
  return out;
}

/** Java string literal. */
const str = (s: string) => JSON.stringify(s);

function partJava(part: ModelPartDef, parent: string, lines: string[], vars: Set<string>): void {
  const boxes = part.boxes
    .map((b) => {
      const [x, y, z, w, h, d] = b.box.map(float);
      const deform = b.inflate ? `new CubeDeformation(${float(b.inflate)})` : "CubeDeformation.NONE";
      return `.texOffs(${b.u}, ${b.v})${b.mirror ? ".mirror()" : ""}.addBox(${x}, ${y}, ${z}, ${w}, ${h}, ${d}, ${deform})${b.mirror ? ".mirror(false)" : ""}`;
    })
    .join("\n\t\t\t\t");
  const [px, py, pz] = part.pivot.map(float);
  const rotated = part.rotation.some((r) => r !== 0);
  const pose = rotated ? `PartPose.offsetAndRotation(${px}, ${py}, ${pz}, ${part.rotation.map(float).join(", ")})` : `PartPose.offset(${px}, ${py}, ${pz})`;
  let v = part.name.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());
  while (vars.has(v)) v += "_";
  vars.add(v);
  const assign = part.children.length ? `PartDefinition ${v} = ` : "";
  lines.push(`\t\t${assign}${parent}.addOrReplaceChild(${str(part.name)}, CubeListBuilder.create()${boxes ? "\n\t\t\t\t" + boxes : ""},\n\t\t\t\t${pose});`);
  for (const child of part.children) partJava(child, v, lines, vars);
}

function animationJava(a: ModelAnimation): string {
  const channels = Object.entries(a.bones).flatMap(([bone, targets]) =>
    (["rotation", "position", "scale"] as const)
      .filter((t) => targets[t]?.length)
      .map((t) => {
        const helper = t === "rotation" ? "degreeVec" : t === "position" ? "posVec" : "scaleVec";
        const frames = targets[t]!.map(
          (k) => `new Keyframe(${float(k.time)}, KeyframeAnimations.${helper}(${k.value.map(float).join(", ")}), AnimationChannel.Interpolations.${k.interpolation.toUpperCase()})`,
        );
        return `\t\t\t.addAnimation(${str(bone)}, new AnimationChannel(AnimationChannel.Targets.${t.toUpperCase()},\n\t\t\t\t${frames.join(",\n\t\t\t\t")}))`;
      }),
  );
  return `AnimationDefinition.Builder.withLength(${float(a.length)})${a.loop ? ".looping()" : ""}\n${channels.join("\n")}\n\t\t\t.build()`;
}

/** The entity model from a Blockbench file: its parts as a LayerDefinition, and its walk and idle animations. */
export function blockbenchModelJava(project: Project, m: MobSpec, model: EntityModelDef): string {
  const P = pascal(m.id);
  const lines: string[] = [];
  const vars = new Set(["mesh", "root"]);
  for (const part of model.parts) partJava(part, "root", lines, vars);
  const { walk, idle } = pickAnimations(model);
  const hasHead = allParts(model.parts).some((p) => p.name === "head");
  const fields = [
    walk && `\tprivate static final AnimationDefinition WALK = ${animationJava(walk)};`,
    idle && `\tprivate static final AnimationDefinition IDLE = ${animationJava(idle)};`,
  ].filter(Boolean);
  const anims = walk || idle;
  return `${GENERATED_HEADER}
package ${project.package}.generated.client;

${[
    ...(anims ? ["net.minecraft.client.animation.AnimationChannel", "net.minecraft.client.animation.AnimationDefinition", "net.minecraft.client.animation.Keyframe", "net.minecraft.client.animation.KeyframeAnimation", "net.minecraft.client.animation.KeyframeAnimations"] : []),
    "net.minecraft.client.model.EntityModel",
    "net.minecraft.client.model.geom.ModelLayerLocation",
    "net.minecraft.client.model.geom.ModelPart",
    "net.minecraft.client.model.geom.PartPose",
    "net.minecraft.client.model.geom.builders.CubeDeformation",
    "net.minecraft.client.model.geom.builders.CubeListBuilder",
    "net.minecraft.client.model.geom.builders.LayerDefinition",
    "net.minecraft.client.model.geom.builders.MeshDefinition",
    "net.minecraft.client.model.geom.builders.PartDefinition",
    "net.minecraft.client.renderer.entity.state.LivingEntityRenderState",
    "net.minecraft.resources.Identifier",
  ].map((i) => `import ${i};`).join("\n")}

import ${project.package}.generated.ModContent;

/** ${m.name}'s body, from ${m.mob.blockbench} (spec/mobs/${m.id}.json). */
public class ${P}Model extends EntityModel<LivingEntityRenderState> {
\tpublic static final ModelLayerLocation LAYER = new ModelLayerLocation(Identifier.fromNamespaceAndPath(ModContent.MOD_ID, ${str(m.id)}), "main");
${fields.length ? "\n" + fields.join("\n\n") + "\n" : ""}${hasHead ? "\n\tprivate final ModelPart head;" : ""}${walk ? "\n\tprivate final KeyframeAnimation walk;" : ""}${idle ? "\n\tprivate final KeyframeAnimation idle;" : ""}

\tpublic ${P}Model(ModelPart root) {
\t\tsuper(root);${hasHead ? '\n\t\tthis.head = root.createPartLookup().apply("head");' : ""}${walk ? "\n\t\tthis.walk = WALK.bake(root);" : ""}${idle ? "\n\t\tthis.idle = IDLE.bake(root);" : ""}
\t}

\tpublic static LayerDefinition createBodyLayer() {
\t\tMeshDefinition mesh = new MeshDefinition();
\t\tPartDefinition root = mesh.getRoot();
${lines.join("\n")}
\t\treturn LayerDefinition.create(mesh, ${model.textureWidth}, ${model.textureHeight});
\t}

\t@Override
\tpublic void setupAnim(LivingEntityRenderState state) {
\t\tsuper.setupAnim(state);${hasHead ? "\n\t\tthis.head.yRot += state.yRot * ((float) Math.PI / 180f);\n\t\tthis.head.xRot += state.xRot * ((float) Math.PI / 180f);" : ""}${idle ? "\n\t\tthis.idle.apply((long) (state.ageInTicks * 50f), 1f);" : ""}${walk ? "\n\t\tthis.walk.applyWalk(state.walkAnimationPos, state.walkAnimationSpeed, 2f, 2.5f);" : ""}
\t}
}
`;
}

/** Draws a mob with its Blockbench model; babies are drawn at half size. */
function blockbenchRendererJava(project: Project, m: MobSpec): string {
  const P = pascal(m.id);
  return `${GENERATED_HEADER}
package ${project.package}.generated.client;

import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.resources.Identifier;

import ${project.package}.generated.ModContent;
import ${project.package}.generated.entity.${P};

/** Draws ${m.name} with its Blockbench model (spec/mobs/${m.id}.json). */
public class ${P}Renderer extends MobRenderer<${P}, LivingEntityRenderState, ${P}Model> {
\tprivate static final Identifier TEXTURE = Identifier.fromNamespaceAndPath(ModContent.MOD_ID, "textures/entity/${m.id}.png");
\tprivate static final Identifier BABY_TEXTURE = Identifier.fromNamespaceAndPath(ModContent.MOD_ID, "textures/entity/${m.id}_baby.png");

\tpublic ${P}Renderer(EntityRendererProvider.Context context) {
\t\tsuper(context, new ${P}Model(context.bakeLayer(${P}Model.LAYER)), ${float(Math.min(m.mob.width, m.mob.height) / 2)});
\t}

\t@Override
\tpublic LivingEntityRenderState createRenderState() {
\t\treturn new LivingEntityRenderState();
\t}

\t@Override
\tpublic Identifier getTextureLocation(LivingEntityRenderState state) {
\t\treturn state.isBaby ? BABY_TEXTURE : TEXTURE;
\t}

\t@Override
\tprotected void scale(LivingEntityRenderState state, PoseStack poseStack) {
\t\tif (state.isBaby) poseStack.scale(0.5f, 0.5f, 0.5f);
\t}
}
`;
}

/** A starter class for `customClass`, written to src/main/java once and never again. */
export function starterClassJava(fqcn: string, kind: "block" | "item" | "plant"): string {
  const dot = fqcn.lastIndexOf(".");
  const pkg = fqcn.slice(0, dot);
  const name = fqcn.slice(dot + 1);
  if (kind === "block" || kind === "plant") {
    const base = kind === "plant" ? "BushBlock" : "Block";
    return `package ${pkg};

import net.minecraft.world.level.block.${base};
import net.minecraft.world.level.block.state.BlockBehaviour;

/**
 * Custom behavior for a block managed by Mod Creator. This file is yours: the generator created it once
 * and will never change it. Override ${base} methods here.
 */
public class ${name} extends ${base} {
\tpublic ${name}(BlockBehaviour.Properties properties) {
\t\tsuper(properties);
\t}
}
`;
  }
  return `package ${pkg};

import net.minecraft.world.item.Item;

/**
 * Custom behavior for an item managed by Mod Creator. This file is yours: the generator created it once
 * and will never change it. Override Item methods here.
 */
public class ${name} extends Item {
\tpublic ${name}(Item.Properties properties) {
\t\tsuper(properties);
\t}
}
`;
}

/** The feature type that places hand-built trees; resources.ts writes each tree's blocks as its config. */
function customTreeFeatureJava(project: Project): string {
  return `${GENERATED_HEADER}
package ${project.package}.generated.world;

import com.mojang.serialization.Codec;
import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.WorldGenLevel;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.LeavesBlock;
import net.minecraft.world.level.block.RotatedPillarBlock;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.ChunkGenerator;
import net.minecraft.world.level.levelgen.feature.Feature;
import net.minecraft.world.level.levelgen.feature.TreeFeature;

/**
 * A tree built by hand in Mod Creator: fixed log and leaf positions relative to the sapling, optionally turned
 * a random quarter turn. Like a vanilla tree it only grows if every block it needs is air or replaceable.
 */
public record CustomTreeFeature(
\t\tBlock log,
\t\tBlock leaves,
\t\tList<BlockPos> logsY,
\t\tList<BlockPos> logsX,
\t\tList<BlockPos> logsZ,
\t\tList<List<BlockPos>> leavesByDistance,
\t\tboolean randomRotation
) implements Feature {
\tpublic static final MapCodec<CustomTreeFeature> CODEC = RecordCodecBuilder.mapCodec(i -> i.group(
\t\t\tBuiltInRegistries.BLOCK.byNameCodec().fieldOf("log").forGetter(CustomTreeFeature::log),
\t\t\tBuiltInRegistries.BLOCK.byNameCodec().fieldOf("leaves").forGetter(CustomTreeFeature::leaves),
\t\t\tBlockPos.CODEC.listOf().optionalFieldOf("logs_y", List.of()).forGetter(CustomTreeFeature::logsY),
\t\t\tBlockPos.CODEC.listOf().optionalFieldOf("logs_x", List.of()).forGetter(CustomTreeFeature::logsX),
\t\t\tBlockPos.CODEC.listOf().optionalFieldOf("logs_z", List.of()).forGetter(CustomTreeFeature::logsZ),
\t\t\tBlockPos.CODEC.listOf().listOf().optionalFieldOf("leaves_by_distance", List.of()).forGetter(CustomTreeFeature::leavesByDistance),
\t\t\tCodec.BOOL.optionalFieldOf("random_rotation", true).forGetter(CustomTreeFeature::randomRotation)
\t).apply(i, CustomTreeFeature::new));

\t@Override
\tpublic MapCodec<CustomTreeFeature> codec() {
\t\treturn CODEC;
\t}

\t@Override
\tpublic boolean place(WorldGenLevel level, ChunkGenerator generator, RandomSource random, BlockPos origin) {
\t\tRotation rotation = this.randomRotation ? Rotation.getRandom(random) : Rotation.NONE;
\t\tfor (List<BlockPos> part : List.of(this.logsY, this.logsX, this.logsZ)) {
\t\t\tfor (BlockPos offset : part) {
\t\t\t\tif (!TreeFeature.validTreePos(level, origin.offset(offset.rotate(rotation)))) return false;
\t\t\t}
\t\t}
\t\tfor (List<BlockPos> ring : this.leavesByDistance) {
\t\t\tfor (BlockPos offset : ring) {
\t\t\t\tif (!TreeFeature.validTreePos(level, origin.offset(offset.rotate(rotation)))) return false;
\t\t\t}
\t\t}
\t\tplaceLogs(level, origin, rotation, this.logsY, Direction.Axis.Y);
\t\tplaceLogs(level, origin, rotation, this.logsX, Direction.Axis.X);
\t\tplaceLogs(level, origin, rotation, this.logsZ, Direction.Axis.Z);
\t\tfor (int i = 0; i < this.leavesByDistance.size(); i++) {
\t\t\tBlockState state = this.leaves.defaultBlockState().trySetValue(LeavesBlock.DISTANCE, Math.min(i + 1, LeavesBlock.DECAY_DISTANCE));
\t\t\tfor (BlockPos offset : this.leavesByDistance.get(i)) {
\t\t\t\tlevel.setBlock(origin.offset(offset.rotate(rotation)), state, Block.UPDATE_ALL);
\t\t\t}
\t\t}
\t\treturn true;
\t}

\tprivate void placeLogs(WorldGenLevel level, BlockPos origin, Rotation rotation, List<BlockPos> offsets, Direction.Axis axis) {
\t\tBlockState state = this.log.defaultBlockState().trySetValue(RotatedPillarBlock.AXIS, axis).rotate(rotation);
\t\tfor (BlockPos offset : offsets) {
\t\t\tBlockPos pos = origin.offset(offset.rotate(rotation));
\t\t\tlevel.setBlock(pos, state, Block.UPDATE_ALL);
\t\t\t// Logs standing on grass turn it to dirt, as vanilla trees do.
\t\t\tif (offset.getY() == 0 && level.getBlockState(pos.below()).is(Blocks.GRASS_BLOCK)) {
\t\t\t\tlevel.setBlock(pos.below(), Blocks.DIRT.defaultBlockState(), Block.UPDATE_ALL);
\t\t\t}
\t\t}
\t}
}
`;
}
